// Intersection of Two Arrays
var table = AnimatedHashTable<Int, Bool>()
let nums1 = [1, 2, 2, 1]
let nums2 = [2, 2, 3]

func intersection(_ arr1: [Int], _ arr2: [Int], t: inout AnimatedHashTable<Int, Bool>) -> [Int] {
    for num in arr1 {
        t.put(num, true)
    }
    var result: [Int] = []
    for num in arr2 {
        if t.get(num) == true {
            result.append(num)
            t.put(num, false)
        }
    }
    return result
}

let intersect = intersection(nums1, nums2, t: &table)
